book page","options":["أمس","صباح","اليوم","مساء"]},"answer":{"correct":"اليوم"}},{"lessonId":"0b066f31-4fd1-4c42-9f09-16082f9e3857","lessonTitle":"ورقة عمل (25) أتعرف الزمن","page":54,"activity_order":4,"activity_type":"fill_blank","title":"أكمل المعنى المناسب","section":"practice","prompt":"اليوم الذي سبق يومنا الحالي يسمى ___ .","content":{"origin":"DADYOOM_BH_G1_10_REMAINING_WORKSHEET_PAGES_50_ORIGINAL_20261030","originalReference":"هذه بطاقة إثرائية أصلية ألّفتها ضاديوم لدعم «ورقة عمل (25) أتعرف الزمن» في موضوع أميز الوقت واليوم السابق. مع المعلم اقرأ المعاني الآتية: «صباح»: الفترة الأولى من النهار بعد شروق الشمس؛ «مساء»: الوقت في آخر النهار؛ «أمس»: اليوم السابق لليوم الحالي؛ «اليوم»: هذا اليوم الذي نعيشه الآن. افهم الصورة أو المثال ثم طبّق ما تعلمته في موقف من صفك أو بيتك. يمكنك أن تشير إلى الإجابة أو تمثلها شفهيًا قبل القراءة المستقلة. الأنشطة الجديدة ليست صورة من ورقة العمل الوزارية، ولم تُثبت مطابقة نص الكتاب أو طبعة العام الدراسي الرسمية؛ إنما هي تدريب مستقل على مهارة قريبة من العنوان.","grade":1,"sourceKind":"supplemental original authoring, source listing does not certify workbook page","items":[{"sentence":"اليوم الذي سبق يومنا الحالي يسمى ___ .","options":["أمس","صباح","اليوم","مساء"]}]},"answer":{"answers":["أمس"]}},{"lessonId":"0b066f31-4fd1-4c42-9f09-16082f9e3857","lessonTitle":"ورقة عمل (25) أتعرف الزمن","page":54,"activity_order":5,"activity_type":"matching","title":"أوصل الكلمة بالتفسير","section":"practice","prompt":"صل كل كلمة بالتفسير الصحيح لها في موضوع «أميز الوقت واليوم السابق».","content":{"origin":"DADYOOM_BH_G1_10_REMAINING_WORKSHEET_PAGES_50_ORIGINAL_20261030","originalReference":"هذه بطاقة إثرائية أصلية ألّفتها ضاديوم لدعم «ورقة عمل (25) أتعرف الزمن» في موضوع أميز الوقت واليوم السابق. مع المعلم اقرأ المعاني الآتية: «صباح»: الفترة الأولى من النهار بعد شروق الشمس؛ «مساء»: الوقت في آخر النهار؛ «أمس»: اليوم السابق لليوم الحالي؛ «اليوم»: هذا اليوم الذي نعيشه الآن. افهم الصورة أو المثال ثم طبّق ما تعلمته في موقف من صفك أو بيتك. يمكنك أن تشير إلى الإجابة أو تمثلها شفهيًا قبل القراءة المستقلة. الأنشطة الجديدة ليست صورة من ورقة العمل الوزارية، ولم تُثبت مطابقة نص الكتاب أو طبعة العام الدراسي الرسمية؛ إنما هي تدريب مستقل على مهارة قريبة من العنوان.","grade":1,"sourceKind":"supplemental original authoring, source listing does not certify workbook page","left":["صباح","مساء","أمس","اليوم"],"right":["هذا اليوم الذي نعيشه الآن","اليوم السابق لليوم الحالي","الوقت في آخر النهار","الفترة الأولى من النهار بعد شروق الشمس"]},"answer":{"pairs":[{"left":"صباح","right":"الفترة الأولى من النهار بعد شروق الشمس"},{"left":"مساء","right":"الوقت في آخر النهار"},{"left":"أمس","right":"اليوم السابق لليوم الحالي"},{"left":"اليوم","right":"هذا اليوم الذي نعيشه الآن"}]}}]$g1work$::jsonb)
AS z("lessonId" text,"lessonTitle" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $check$
DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_grade1_10_worksheet_50)<>50
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_grade1_10_worksheet_50)<>10
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_grade1_10_worksheet_50)<>50
 OR EXISTS(SELECT 1 FROM pg_temp.bh_grade1_10_worksheet_50 x WHERE
 x.activity_order NOT BETWEEN 2 AND 6 OR length(x.prompt)<15 OR length(x.content->>'originalReference')<260
 OR x.content ? 'correct' OR x.content ? 'answer'
 OR (x.activity_type='multiple_choice' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'options') t WHERE t=x.answer->>'correct'))
 OR (x.activity_type='fill_blank' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'items'->0->'options') t WHERE t=x.answer->'answers'->>0))
 OR (x.activity_type='matching' AND jsonb_array_length(x.answer->'pairs')<>jsonb_array_length(x.content->'left')))
 THEN RAISE EXCEPTION 'Invalid ten original worksheet question data'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade1_10_worksheet_50 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE co.code='BH' AND g.grade_number=1 AND l.status='published' AND l.source_pdf_url IS NOT NULL
 AND l.content LIKE '%إثراء ضاديوم الأصلي%'
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=1
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=1
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts a JOIN public.lesson_activities x ON x.id=a.activity_id WHERE x.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts a JOIN public.questions q ON q.id=a.question_id WHERE q.lesson_id=l.id);
 IF eligible<>10 THEN RAISE EXCEPTION 'Bahrain Grade1 worksheet/history scope changed (% / 10)',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_G1_10_REMAINING_WORKSHEET_PAGES_50_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Idempotency: current worksheet batch already loaded'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'تدريب أصلي إضافي من ضاديوم، اقرأه أو استمع إليه مع المعلم ثم أجب.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade1_10_worksheet_50 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE co.code='BH' AND g.grade_number=1 AND l.status='published'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts a JOIN public.lesson_activities x ON x.id=a.activity_id WHERE x.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts a JOIN public.questions q ON q.id=a.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>50 THEN RAISE EXCEPTION 'Atomic rollback: inserted % / 50',inserted; END IF;
END $check$;
COMMIT;